1|static void test_simple_values(void** _state _CBOR_UNUSED) {
2|  // 0..23 use the one-byte encoding
3|  assert_size_equal(1, cbor_encode_ctrl(0, buffer, 512));
4|  assert_memory_equal(buffer, ((unsigned char[]){0xE0}), 1);
5|  assert_size_equal(1, cbor_encode_ctrl(19, buffer, 512));
6|  assert_memory_equal(buffer, ((unsigned char[]){0xF3}), 1);
7|  assert_size_equal(1, cbor_encode_ctrl(20, buffer, 512));
8|  assert_memory_equal(buffer, ((unsigned char[]){0xF4}), 1);
9|  assert_size_equal(1, cbor_encode_ctrl(23, buffer, 512));
10|  assert_memory_equal(buffer, ((unsigned char[]){0xF7}), 1);
11|
12|  // 32..255 use the two-byte encoding
13|  assert_size_equal(2, cbor_encode_ctrl(32, buffer, 512));
14|  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x20}), 2);
15|  assert_size_equal(2, cbor_encode_ctrl(255, buffer, 512));
16|  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0xFF}), 2);
17|
18|  // 24..31 are reserved by RFC 8949 and have no well-formed encoding. The
19|  // encoder does not reject them; this pins the current (ill-formed) output
20|  // so that any change is deliberate.
21|  assert_size_equal(2, cbor_encode_ctrl(24, buffer, 512));
22|  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x18}), 2);
23|  assert_size_equal(2, cbor_encode_ctrl(31, buffer, 512));
24|  assert_memory_equal(buffer, ((unsigned char[]){0xF8, 0x1F}), 2);
25|
26|  // Insufficient buffer
27|  assert_size_equal(0, cbor_encode_ctrl(0, buffer, 0));
28|  assert_size_equal(0, cbor_encode_ctrl(32, buffer, 1));
29|}

