20|      .uint8 = &cbor_builder_uint8_callback,
21|      .uint16 = &cbor_builder_uint16_callback,
22|      .uint32 = &cbor_builder_uint32_callback,
23|      .uint64 = &cbor_builder_uint64_callback,
24|
