28|      .negint64 = &cbor_builder_negint64_callback,
29|
30|      .byte_string = &cbor_builder_byte_string_callback,
31|      .byte_string_start = &cbor_builder_byte_string_start_callback,
32|
33|      .string = &cbor_builder_string_callback,
34|      .string_start = &cbor_builder_string_start_callback,
35|
36|      .array_start = &cbor_builder_array_start_callback,
37|      .indef_array_start = &cbor_builder_indef_array_start_callback,
38|
39|      .map_start = &cbor_builder_map_start_callback,
40|      .indef_map_start = &cbor_builder_indef_map_start_callback,
41|
42|      .tag = &cbor_builder_tag_callback,
43|
44|      .null = &cbor_builder_null_callback,
45|      .undefined = &cbor_builder_undefined_callback,
46|      .boolean = &cbor_builder_boolean_callback,
47|      .float2 = &cbor_builder_float2_callback,
48|      .float4 = &cbor_builder_float4_callback,
49|      .float8 = &cbor_builder_float8_callback,
50|      .indef_break = &cbor_builder_indef_break_callback};
51|
52|  if (source_size == 0) {
53|    result->error.code = CBOR_ERR_NODATA;
54|    return NULL;
55|  }
56|  struct _cbor_stack stack = _cbor_stack_init();
57|
58|  /* Target for callbacks */
59|  struct _cbor_decoder_context context = (struct _cbor_decoder_context){
60|      .stack = &stack, .creation_failed = false, .syntax_error = false};
61|  struct cbor_decoder_result decode_result;
62|  *result =
63|      (struct cbor_load_result){.read = 0, .error = {.code = CBOR_ERR_NONE}};
64|
65|  do {
66|    if (source_size > result->read) { /* Check for overflows */
67|      decode_result =
68|          cbor_stream_decode(source + result->read, source_size - result->read,
69|                             &callbacks, &context);
70|    } else {
71|      result->error = (struct cbor_error){.code = CBOR_ERR_NOTENOUGHDATA,
72|                                          .position = result->read};
73|      goto error;
74|    }
75|
76|    switch (decode_result.status) {
77|      case CBOR_DECODER_FINISHED:
78|        /* Everything OK */
79|        {
80|          result->read += decode_result.read;
81|          break;
82|        }
83|      case CBOR_DECODER_NEDATA:
84|        /* Not enough data to complete the current item */
85|        {
86|          result->error.code = CBOR_ERR_NOTENOUGHDATA;
87|          goto error;
88|        }
89|      case CBOR_DECODER_ERROR:
90|        /* Reserved/malformed item */
91|        {
92|          result->error.code = CBOR_ERR_MALFORMATED;
93|          goto error;
94|        }
95|    }
96|
97|    if (context.creation_failed) {
98|      /* Most likely unsuccessful allocation - our callback has failed */
99|      result->error.code = CBOR_ERR_MEMERROR;
100|      goto error;
101|    } else if (context.syntax_error) {
102|      result->error.code = CBOR_ERR_SYNTAXERROR;
103|      goto error;
104|    }
105|  } while (stack.size > 0);
106|
107|  return context.root;
108|
109|error:
110|  result->error.position = result->read;
111|  // debug_print("Failed with decoder error %d at %d\n", result->error.code,
112|  // result->error.position); cbor_describe(stack.top->item, stdout);
113|  /* Free the stack */
114|  while (stack.size > 0) {
115|    cbor_decref(&stack.top->item);
116|    _cbor_stack_pop(&stack);
117|  }
118|  return NULL;
