166|cbor_item_t* cbor_copy(cbor_item_t* item) {
167|  CBOR_ASSERT_VALID_TYPE(cbor_typeof(item));
168|  switch (cbor_typeof(item)) {
169|    case CBOR_TYPE_UINT:
170|      return _cbor_copy_int(item, false);
171|    case CBOR_TYPE_NEGINT:
172|      return _cbor_copy_int(item, true);
173|    case CBOR_TYPE_BYTESTRING:
174|      if (cbor_bytestring_is_definite(item)) {
175|        return cbor_build_bytestring(cbor_bytestring_handle(item),
176|                                     cbor_bytestring_length(item));
177|      } else {
178|        cbor_item_t* res = cbor_new_indefinite_bytestring();
179|        if (res == NULL) {
180|          return NULL;
181|        }
182|
