12|void *limited_malloc(size_t size) {
13|    if (size + allocated_mem > kMemoryLimit) {
14|        return nullptr;
15|    }
16|    if (size == 0) {
17|        return nullptr;
18|    }
19|    void* m = malloc(size);
20|    if (m != nullptr) {
21|        allocated_mem += size;
22|        allocated_len_map[m] = size;
23|    }
24|    return m;
25|}

